        topic: 'selected-day-summary-file',
        dateKey: selectedDate,
        payload: shellCommand,
        summaryFileName,
        energyFileName
    },
    {
        topic: 'selected-day-summary-loading',
        dateKey: selectedDate,
        payload: '',
        summaryFileName,
        energyFileName
    }
];

